// Extraire les données du job
const input = $input.first().json;

let commentaries = [];
let body = input;

if (input.body && Array.isArray(input.body.commentaries)) {
  commentaries = input.body.commentaries;
  body = input.body;
} else if (Array.isArray(input.commentaries)) {
  commentaries = input.commentaries;
} else if (input.body && typeof input.body === 'string') {
  try {
    const parsed = JSON.parse(input.body);
    if (Array.isArray(parsed.commentaries)) {
      commentaries = parsed.commentaries;
      body = parsed;
    }
  } catch(e) {}
}

return [{
  json: {
    jobId: body.job_id || input.job_id,
    textName: body.text_name || input.text_name,
    chapter: body.chapter || input.chapter,
    commentator: body.commentator || input.commentator,
    targetLanguage: body.target_language || input.target_language || 'fr',
    apiKey: body.api_key || input.api_key,
    openaiApiKey: body.openai_api_key || input.openai_api_key,
    commentaries: commentaries,
    commentariesCount: commentaries.length
  }
}];

// Passer les données originales
const prevData = $('Parse Input').first().json;
return [{ json: prevData }];

// Convertir les commentaires en items pour la boucle
const input = $input.first().json;

const items = input.commentaries.map((commentary, index) => {
  return {
    json: {
      commentaryIndex: index,
      commentaryId: commentary.id,
      commentator: commentary.commentator,
      reference: commentary.reference,
      commentaryText: commentary.hebrew_text || commentary.text || '',
      verseText: commentary.verse_text || '',
      verse: commentary.verse,
      totalCommentaries: input.commentaries.length,
      jobId: input.jobId,
      textName: input.textName,
      chapter: input.chapter,
      targetLanguage: input.targetLanguage,
      apiKey: input.apiKey,
      openaiApiKey: input.openaiApiKey
    }
  };
});

return items;

